import{_ as r,o as t,c as o,a4 as a}from"./chunks/framework.DpieW3qv.js";const p=JSON.parse('{"title":"Producer Review: 4 Web Producers (2 per Brand)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/producer-review-4-personas.md","filePath":"guides/producer-review-4-personas.md","lastUpdated":null}'),s={name:"guides/producer-review-4-personas.md"};function i(n,e,d,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="producer-review-4-web-producers-2-per-brand" tabindex="-1">Producer Review: 4 Web Producers (2 per Brand) <a class="header-anchor" href="#producer-review-4-web-producers-2-per-brand" aria-label="Permalink to &quot;Producer Review: 4 Web Producers (2 per Brand)&quot;">​</a></h1><p>Assessment of the application for <strong>4 web producers</strong> (2 LOFT, 2 Ann Taylor) who previously used a <strong>manual process</strong>. For the actual daily flow and setup, use <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a> and <a href="/ocapi-docs.github.io/guides/quick-start.html">Quick Start</a>. See <a href="/ocapi-docs.github.io/guides/producer-guides-overview.html">Producer guides overview</a> for how all producer guides fit together.</p><hr><h2 id="who-they-are" tabindex="-1">Who They Are <a class="header-anchor" href="#who-they-are" aria-label="Permalink to &quot;Who They Are&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Count</th><th>Brand(s)</th><th>Old Way</th></tr></thead><tbody><tr><td>Web Producer (LOFT)</td><td>2</td><td>LOFT</td><td>Manual Excel → manual HTML/copy → manual SFCC upload or campaign setup</td></tr><tr><td>Web Producer (Ann Taylor)</td><td>2</td><td>Ann Taylor</td><td>Same</td></tr></tbody></table><p><strong>Manual way (before this tool):</strong> Producers would typically take wireframe data (Smartsheet/Excel), build or copy content into HTML or SFCC by hand, upload assets, configure campaigns and slots in Business Manager (or similar), then send changeout emails. Error-prone, repetitive, and hard to coordinate when two people work the same brand.</p><hr><h2 id="fit-summary" tabindex="-1">Fit Summary <a class="header-anchor" href="#fit-summary" aria-label="Permalink to &quot;Fit Summary&quot;">​</a></h2><p>The app gives them a single flow (pull → build → preview → push → done → commit), sticky date, build/sync guards, data quality checks before push, and multi-producer safety via Git. Strengths: no need to touch configs/templates, guards prevent overwriting a partner’s work, and the full how-to lives in <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a> and <a href="/ocapi-docs.github.io/guides/multi-producer.html">Multi-Producer Guide</a>.</p><hr><h2 id="gaps-and-risks-manual-→-tooling" tabindex="-1">Gaps and Risks (Manual → Tooling) <a class="header-anchor" href="#gaps-and-risks-manual-→-tooling" aria-label="Permalink to &quot;Gaps and Risks (Manual → Tooling)&quot;">​</a></h2><h3 id="_1-brand-is-global-not-per-producer" tabindex="-1">1. Brand is global, not per-producer <a class="header-anchor" href="#_1-brand-is-global-not-per-producer" aria-label="Permalink to &quot;1. Brand is global, not per-producer&quot;">​</a></h3><ul><li><strong>Reality:</strong> <code>dev-env/.ocapi-config.json</code> has one <code>brand</code> (and one Excel path). The Makefile uses <code>BRAND ?= (from config)</code>.</li><li><strong>Risk:</strong> If Producer A (LOFT) and Producer B (Ann) work on the same machine (e.g. shared dev box), they must remember <code>make switch TO=...</code> or they’ll run commands for the wrong brand.</li><li><strong>Mitigation:</strong> Docs already say “Wrong brand → make switch TO=loft/ann”. For 2-per-brand, usually each person has their own machine and stays on one brand; switching matters for backups or multi-brand producers.</li></ul><h3 id="_2-fix-in-excel-and-re-fetch-can-feel-slow" tabindex="-1">2. “Fix in Excel and re-fetch” can feel slow <a class="header-anchor" href="#_2-fix-in-excel-and-re-fetch-can-feel-slow" aria-label="Permalink to &quot;2. “Fix in Excel and re-fetch” can feel slow&quot;">​</a></h3><ul><li><strong>Reality:</strong> Data quality errors say “Fix the issues in the Excel and re-fetch with make pull.”</li><li><strong>Risk:</strong> Producers used to fixing things in SFCC or in local HTML may expect to fix in the repo and re-push. The tool enforces “source of truth = Excel/Smartsheet” and re-fetch.</li><li><strong>Mitigation:</strong> Ecomm workflow doc explains that the wireframe is source of truth; producers need to know that data fixes go in Excel/Smartsheet, then <code>make pull</code> and rebuild.</li></ul><h3 id="_3-multiple-refreshes-per-date-r1-r2" tabindex="-1">3. Multiple refreshes per date (r1, r2) <a class="header-anchor" href="#_3-multiple-refreshes-per-date-r1-r2" aria-label="Permalink to &quot;3. Multiple refreshes per date (r1, r2)&quot;">​</a></h3><ul><li><strong>Reality:</strong> Some dates have <code>r1</code>, <code>r2</code>; if they only pass <code>DATE=</code>, the CLI uses sticky or prompts. Non-interactive (scripts/CI) must pass <code>REFRESH=r#</code> or <code>ALL=1</code>.</li><li><strong>Risk:</strong> A producer who runs <code>make push DATE=2026-02-14</code> in a script or from a cron might get “multiple refreshes: r1, r2” and no push.</li><li><strong>Mitigation:</strong> Docs (push, reference) already say: “If REFRESH is omitted on a multi-refresh date … interactive refresh picker (TTY) … explicit error in non-interactive (provide REFRESH or ALL=1).” Producers in TTY get the picker; they just need to know that <code>DATE=… REFRESH=r2</code> is required when not using the picker.</li></ul><h3 id="_4-replicate-is-still-manual" tabindex="-1">4. Replicate is still manual <a class="header-anchor" href="#_4-replicate-is-still-manual" aria-label="Permalink to &quot;4. Replicate is still manual&quot;">​</a></h3><ul><li><strong>Reality:</strong> <code>make replicate</code> opens a <strong>checklist</strong> for STG → POD; it does not perform replication itself.</li><li><strong>Risk:</strong> Producers might expect “make push = staging, make replicate = production” to be one click. It’s intentional that production is a separate, manual step.</li><li><strong>Mitigation:</strong> Quick start and push docs say “Production deployment requires manual replication via make replicate”; producer workflow and multi-producer guide reinforce that.</li></ul><h3 id="_5-first-time-setup-and-credentials" tabindex="-1">5. First-time setup and credentials <a class="header-anchor" href="#_5-first-time-setup-and-credentials" aria-label="Permalink to &quot;5. First-time setup and credentials&quot;">​</a></h3><ul><li><strong>Reality:</strong> <code>make setup</code> configures brand and OCAPI toggle; SFCC credentials are env vars (<code>SFCC_BASE_URL</code>, <code>SFCC_CLIENT_ID</code>, etc.). <code>make health</code> verifies.</li><li><strong>Risk:</strong> New producers (or a new machine) must have env set; otherwise push fails with auth/OCAPI errors.</li><li><strong>Mitigation:</strong> Quick start says “make setup” then “make pull”; troubleshooting and push say “OCAPI not enabled → make setup, make health.” A short “first day” checklist (see below) would help.</li></ul><h3 id="_6-terminology-sfcc-already-has-this-date" tabindex="-1">6. Terminology: “SFCC already has this date” <a class="header-anchor" href="#_6-terminology-sfcc-already-has-this-date" aria-label="Permalink to &quot;6. Terminology: “SFCC already has this date”&quot;">​</a></h3><ul><li><strong>Reality:</strong> After the recent change, when nothing is new to sync the message is “SFCC already has this date; no changes to sync” (and slot binding is skipped).</li><li><strong>Risk:</strong> Producers who are used to “Already synced” might look for that exact phrase; docs and CLI are aligned on the new wording.</li><li><strong>Mitigation:</strong> Producer workflow and multi-producer docs should use the same phrase where they describe the “no second push” behavior (see recommendation below).</li></ul><hr><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations&quot;">​</a></h2><h3 id="for-product-docs" tabindex="-1">For product/docs <a class="header-anchor" href="#for-product-docs" aria-label="Permalink to &quot;For product/docs&quot;">​</a></h3><ol><li><p><strong>First-day checklist</strong> lives in <a href="/ocapi-docs.github.io/guides/quick-start.html">Quick Start</a>: clone, <code>npm install</code>, <code>make setup</code>, set SFCC env vars, <code>make health</code>, then <code>make pull</code> → pick date → build → preview → push. Add “If you work both brands, use <code>make switch TO=ann</code> / <code>make switch TO=loft</code>” there if not already present.</p></li><li><p><strong>Emphasize “fix in Excel, then make pull”</strong><br> Data quality errors are fixed in the Excel/Smartsheet; then run <code>make pull</code> and try <code>make push</code> again. Producer Workflow and troubleshooting already state this; keep it in one place (e.g. Producer Workflow).</p></li><li><p><strong>Multi-refresh</strong><br> For a date with multiple refreshes (r1, r2), use the interactive picker or pass <code>REFRESH=r2</code> (or <code>ALL=1</code>). Documented in <a href="/ocapi-docs.github.io/cli/push.html">push</a> and <a href="/ocapi-docs.github.io/reference/commands.html">Commands Reference</a>.</p></li></ol><h3 id="for-the-4-producers" tabindex="-1">For the 4 producers <a class="header-anchor" href="#for-the-4-producers" aria-label="Permalink to &quot;For the 4 producers&quot;">​</a></h3><ul><li><strong>2 per brand:</strong> Each producer runs on their own machine, sticky date is personal, build/sync guards protect the other. Always <code>make pull</code> first and <code>make commit</code> + <code>git push</code> after push/done.</li><li><strong>If someone covers both brands:</strong> Use <code>make switch TO=...</code> and run <code>make status</code> to confirm brand before building/pushing.</li><li><strong>Manual legacy:</strong> They no longer hand-edit HTML for standard flows or manually create campaigns in BM; the tool generates and syncs. Hotfix path: edit template → <code>make edit</code> → <code>make push</code> (and optionally <code>FORCE=1</code> if already synced).</li></ul><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Assessment</th></tr></thead><tbody><tr><td><strong>Fit for 4 producers (2 per brand)</strong></td><td>Good: sticky date, guards, Git-based sharing, clear flow.</td></tr><tr><td><strong>Transition from manual</strong></td><td>Good: one linear flow, data quality before SFCC, preview; need clear “source of truth = Excel” and first-day setup.</td></tr><tr><td><strong>Brand switching</strong></td><td>Documented; matters only if one person works both brands.</td></tr><tr><td><strong>Multi-refresh dates</strong></td><td>Handled via sticky + picker or <code>REFRESH=</code> / <code>ALL=1</code>; docs are adequate; one consolidated sentence helps.</td></tr><tr><td><strong>Replicate / production</strong></td><td>By design manual; docs state it.</td></tr><tr><td><strong>Docs consistency</strong></td><td>Small fix: use “SFCC already has this date” in producer-facing docs where the push guard is described.</td></tr></tbody></table><p>The application is well-aligned with 4 web producers (2 per brand) moving from a manual build/deploy process, with minor doc and onboarding tweaks recommended above.</p>',33)])])}const m=r(s,[["render",i]]);export{p as __pageData,m as default};
